insert into bourdain_locations
  (show, season, episode, episode_title, location_name, city, country, lat, lng, description, air_date)
values
  ('no_reservations', 1, 1, 'France: Why the French Don''t Suck', 'Paris', 'Paris', 'France', 48.856614, 2.352222, 'Tony''s debut episode of this new series has him visiting Paris. He explores the city''s famous catacombs, tries some absinthe, checks out one of the city''s major meat markets, and spends the night in the room where Oscar Wilde died.', '2005-07-25'),
  ('no_reservations', 1, 2, 'Iceland: Hello Darkness My Old Friend', 'Reykjavík', 'Reykjavík', 'Iceland', 64.126521, -21.817439, 'This week Anthony travels to Reykjavík, Iceland, where in winter the volcanic islands see only about four hours of sunlight a day. Anthony finds the darkness comforting and learns how the Icelanders contend with the dark days - eating, drinking, spending time at the spa, and pumping iron! Tony tries Hákarl (fermented shark). Later, he visits the famous Blue Lagoon.', '2005-08-01'),
  ('no_reservations', 1, 3, 'New Jersey', 'Fort Lee', 'Fort Lee', 'USA', 40.850933, -73.970138, 'Tony visits the state of New Jersey. He takes us on a trip through his birthplace trying to dispel some common misconceptions of the Garden State. We learn about The Sopranos and other NJ landmarks as Tony reminisces. He also meets up with Nari Kye, an assistant, who teaches him Korean food.', '2005-08-08'),
  ('no_reservations', 1, 3, 'New Jersey', 'Barnegat Light', 'Barnegat Light', 'USA', 39.75762, -74.106247, 'Tony visits the state of New Jersey. He takes us on a trip through his birthplace trying to dispel some common misconceptions of the Garden State. We learn about The Sopranos and other NJ landmarks as Tony reminisces. He also meets up with Nari Kye, an assistant, who teaches him Korean food.', '2005-08-08'),
