  ('no_reservations', 4, 18, 'Egypt', 'Seds', 'Seds', 'Egypt', 30.063678, 31.219527, 'Tony is determined to avoid doing the tourist thing and visiting the Egyptian pyramids, but rather explore what it means to be Egyptian; to spending an evening at a men''s cafe smoking Shisha, to a boat ride down the Nile and spending time in the desert with a group of Bedouin men.', '2008-08-25'),
  ('no_reservations', 4, 18, 'Egypt', 'Cairo', 'Cairo', 'Egypt', 30.04442, 31.235712, 'Tony is determined to avoid doing the tourist thing and visiting the Egyptian pyramids, but rather explore what it means to be Egyptian; to spending an evening at a men''s cafe smoking Shisha, to a boat ride down the Nile and spending time in the desert with a group of Bedouin men.', '2008-08-25'),
  ('no_reservations', 4, 18, 'Egypt', 'Luxor', 'Luxor', 'Egypt', 25.687243, 32.639636, 'Tony is determined to avoid doing the tourist thing and visiting the Egyptian pyramids, but rather explore what it means to be Egyptian; to spending an evening at a men''s cafe smoking Shisha, to a boat ride down the Nile and spending time in the desert with a group of Bedouin men.', '2008-08-25'),
  ('no_reservations', 4, 19, 'So Long, Summer', 'Manhattan, New York', 'Manhattan', 'USA', 40.78306, -73.971249, NULL, NULL),
