  ('no_reservations', 6, 19, 'Dubai', 'Dubai', 'Dubai', 'United Arab Emirates', 25.204849, 55.270783, 'Tony visits Dubai and samples some of the local highlights, including fine dining and the indoor ski resort Ski Dubai. He also meets and eats with some of the locals, including young sheiks and foreign workers.', '2010-08-09'),
  ('no_reservations', 6, 20, 'Rome', 'Rome', 'Rome', 'Italy', 41.902783, 12.496366, 'Tony visits Rome, Italy and meets artisans of pasta, cheese and other local specialties. The episode was filmed entirely in black and white and is intended as an homage to Federico Fellini''s films, especially La Dolce Vita.', '2010-08-16'),
  ('no_reservations', 6, 21, 'Back to Beirut', 'Beirut', 'Beirut', 'Lebanon', 33.893791, 35.501777, 'Tony and crew return to Beirut after their last attempt was derailed by the 2006 Lebanon War.', '2010-08-23'),
